// Money formatting helper - preserves exact decimals, shows 2 decimal places
const money = (n) => {
  const value = Number(n) || 0;
  // Don't round - preserve exact decimal precision, just format for display
  return value.toLocaleString(undefined, { 
    style: 'currency', 
    currency: 'USD',
    minimumFractionDigits: 2,
    maximumFractionDigits: 2 
  });
};

/** Shorter labels for narrow bar-chart columns (avoids $5,052,000.00 wrapping). */
const moneyCompactBar = (n) => {
  const value = Number(n) || 0;
  const abs = Math.abs(value);
  const sign = value < 0 ? '-' : '';
  if (abs >= 1_000_000) {
    return `${sign}$${(abs / 1_000_000).toFixed(2)}M`;
  }
  if (abs >= 100_000) {
    return `${sign}$${(abs / 1_000).toFixed(1)}K`;
  }
  return money(value);
};

